import json
import glob
import os

# Find all JSONL files in /app
jsonl_files = glob.glob('/app/records_*.jsonl')

# Initialize accumulators
user_data = {}  # user -> {"total_amount": float, "total_items": int}
tag_counts = {}  # tag -> count

for filepath in jsonl_files:
    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                record = json.loads(line)
                user = record['user']
                amount = record['amount']
                items = record['items']
                tags = record.get('tags', [])

                # Update user data
                if user not in user_data:
                    user_data[user] = {"total_amount": 0, "total_items": 0}
                user_data[user]["total_amount"] += amount
                user_data[user]["total_items"] += items

                # Count tags
                for tag in tags:
                    tag_counts[tag] = tag_counts.get(tag, 0) + 1
            except json.JSONDecodeError:
                continue

# Calculate top 5 users by amount (sorted by total_amount descending)
# We need the top 5 users based on total_amount
sorted_users = sorted(user_data.items(), key=lambda x: x[1]["total_amount"], reverse=True)
top_5_users = {}
for user, data in sorted_users[:5]:
    # Round amount to 2 decimal places
    top_5_users[user] = {
        "total_amount": round(data["total_amount"], 2),
        "total_items": int(data["total_items"])
    }

# Calculate top 5 tags by count
sorted_tags = sorted(tag_counts.items(), key=lambda x: x[1], reverse=True)
top_5_tags = {}
for tag, count in sorted_tags[:5]:
    top_5_tags[tag] = {"count": int(count)}

# Create the final structure
result = {
    "top_5_users_by_amount": top_5_users,
    "top_5_tags_by_count": top_5_tags
}

# Write to /app/aggregates.json
with open('/app/aggregates.json', 'w') as f:
    json.dump(result, f)

print("Done!")
EOF"}

